static int spiral(unsigned int turns,unsigned int seg,p2d89_q14 r0,p2d89_q14 r1,int cw,p2d89_u16 rot,const P2D89_Provider *p){unsigned int i;p2d89_u32 span,phase;p2d89_i32 rv,dr;p2d89_q14 sn,cs,r,x,y;span=(p2d89_u32)turns*256U;dr=(p2d89_i32)r1-(p2d89_i32)r0;for(i=0U;i<=seg;++i){phase=(span*i)/seg;if(cw)phase=(p2d89_u32)(0U-phase);phase=(phase+(p2d89_u32)rot)&65535U;rv=(p2d89_i32)r0+(dr*(p2d89_i32)i)/(p2d89_i32)seg;r=(p2d89_q14)rv;p2d89_sincos_turn((p2d89_u16)phase,&sn,&cs);x=p2d89_mul_q14(cs,r);y=p2d89_mul_q14(sn,r);if(i==0U){if(!p2d89_i_move(p,x,y))return 0;}else if(!p2d89_i_line(p,x,y))return 0;}return 1;}
static int emit(P2D89_ShapeId id,const P2D89_Provider *p){if(id==P2D89_SHAPE_SPIRAL_ARCHIMEDEAN_1)return spiral(256U,32U,512,P2D89_ONE,0,0U,p);if(id==P2D89_SHAPE_SPIRAL_ARCHIMEDEAN_2)return spiral(512U,48U,512,P2D89_ONE,0,0U,p);if(id==P2D89_SHAPE_SPIRAL_ARCHIMEDEAN_3)return spiral(768U,64U,512,P2D89_ONE,0,0U,p);if(id==P2D89_SHAPE_SPIRAL_ARCHIMEDEAN_4)return spiral(1024U,80U,512,P2D89_ONE,0,0U,p);if(id==P2D89_SHAPE_SPIRAL_CLOCKWISE)return spiral(768U,64U,768,P2D89_ONE,1,0U,p);if(id==P2D89_SHAPE_SPIRAL_COUNTERCLOCKWISE)return spiral(768U,64U,768,P2D89_ONE,0,0U,p);if(id==P2D89_SHAPE_DOUBLE_SPIRAL){if(!spiral(640U,48U,512,P2D89_ONE,0,0U,p))return 0;return spiral(640U,48U,512,P2D89_ONE,0,32768U,p);}if(id==P2D89_SHAPE_SPIRAL_HOOK)return spiral(384U,40U,4096,P2D89_ONE,0,49152U,p);if(id==P2D89_SHAPE_SPIRAL_INWARD)return spiral(768U,64U,P2D89_ONE,512,0,0U,p);if(id==P2D89_SHAPE_SPIRAL_OUTWARD)return spiral(768U,64U,512,P2D89_ONE,0,0U,p);return 0;}
